    const range = spec.range.map(value => typeof value === 'string' && d3Color(value) ? paint(value) : String(value));
    const options = Object.entries(spec.options).map(([key,value]) => `${key}={${key === 'unknown' ? paint(value) : String(value)}}`).join(',');
