        console.log(`[DEBUG] Gallery carrier ${language}/${entry.slug}: frame=${JSON.stringify(frame)} body=${JSON.stringify(panel)} ink=${JSON.stringify(bounds)} textItems=${texts.get(`SemioCarrier${index}`)?.length ?? 0}`);
